const FOUNDATION_CONSTRUCTION_BYTES: Option<usize> = {
    let terms: [(usize, usize); 9] = [
        (3, size_of::<ValidatedSwiftReactor>()),
        (3, size_of::<RuntimeControl>()),
        (3, size_of::<AdoptedProof>()),
        (4, size_of::<SwiftRunFailure>()),
